SELECT o.status, CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, MAX(oi.unit_price) - MIN(oi.unit_price) AS unit_price_range, SUM(oi.unit_price) AS total_unit_price FROM order_items oi INNER JOIN products p ON oi.product_id = p.id LEFT JOIN orders o ON o.id = oi.order_id GROUP BY o.status, CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END
